import { cn } from "~/lib/utils.ts";

import { type Component, type ComponentProps, splitProps } from "solid-js";

const Kbd: Component<ComponentProps<"kbd">> = (props) => {
  const [local, others] = splitProps(props, ["class"]);
  return (
    <kbd
      data-slot="kbd"
      class={cn(
        "bg-muted text-muted-foreground in-data-[slot=tooltip-content]:bg-background/20 in-data-[slot=tooltip-content]:text-background dark:in-data-[slot=tooltip-content]:bg-background/10 h-5 w-fit min-w-5 gap-1 rounded-lg px-1 font-sans text-xs font-medium [&_svg:not([class*='size-'])]:size-3 in-data-[slot=input-group]:bg-input pointer-events-none inline-flex select-none items-center justify-center",
        local.class,
      )}
      {...others}
    />
  );
};

const KbdGroup: Component<ComponentProps<"kbd">> = (props) => {
  const [local, others] = splitProps(props, ["class"]);
  return (
    <kbd
      data-slot="kbd-group"
      class={cn("gap-1 inline-flex items-center", local.class)}
      {...others}
    />
  );
};

export { Kbd, KbdGroup };
